    text_tr: '1950 tarihli \'Teoloji ve Yanlışlanabilirlik\' adlı makalesinde, görünmez ve dokunulmaz bir bahçıvana ilişkin bir kıssayı yeniden anlatarak dindarları, Tanrı hakkındaki iddialarına karşı hangi kanıtın -varsa- sayılabileceğini belirtmeye çağıran filozof kimdir?',
