    text: 'Which contemporary Christian philosopher\'s \'free will defense\' responds to the logical problem of evil by arguing that God could not create a world containing genuinely free creatures who are guaranteed never to choose evil?',
    text_tr: 'Tanrı\'nın, kötülüğü asla seçmeyeceği garanti edilen gerçekten özgür yaratıklar içeren bir dünya yaratamayacağını savunarak kötülüğün mantıksal problemine \'özgür irade savunması\' ile yanıt veren çağdaş Hıristiyan filozof kimdir?',
    options: { A: 'Alvin Plantinga', B: 'John Hick', C: 'Richard Swinburne', D: 'William Lane Craig', E: 'Nicholas Wolterstorff' },
