    text_tr: 'Asanga ve Vasubandhu kardeşlerle ilişkilendirilen ve deneyimlenen tüm görüngülerin bilincin (\'vijnana\') kurgusu ya da temsili olduğunu öğreterek \'yalnızca zihin\' adını alan Mahayana Budist felsefe okulu hangisidir?',
    options: { A: 'Yogacara', B: 'Madhyamaka', C: 'Theravada', D: 'Pure Land', E: 'Sarvastivada' },
