    text: 'Which philosopher\'s essay \'The Politics of Recognition\' argued that a person\'s or a group\'s identity is partly shaped by whether it receives due recognition from others, so that misrecognition can constitute a genuine form of harm?',
    text_tr: '\'Tanınma Siyaseti\' başlıklı denemesinde, bir kişinin veya grubun kimliğinin kısmen başkalarından gördüğü tanınmayla şekillendiğini, dolayısıyla yanlış tanınmanın gerçek bir zarar biçimi oluşturabileceğini savunan filozof kimdir?',
