    text: 'Which German political theorist declared that \'sovereign is he who decides on the exception,\' and argued that the fundamental distinction defining the political as such is that between friend and enemy?',
    text_tr: '\'Egemen olan, istisna hakkında karar verendir\' diyen ve siyasal olanı tanımlayan temel ayrımın dost ile düşman arasındaki ayrım olduğunu savunan Alman siyaset kuramcısı kimdir?',
    options: { A: 'Max Weber', B: 'Carl Schmitt', C: 'Leo Strauss', D: 'Hannah Arendt', E: 'Jürgen Habermas' },
