    text_tr: '12. yüzyıl filozof-teologlarından hangisi, ortaçağın tümel sorununu \'kavramcılık\' adı verilen ılımlı bir konumla çözmüş, tümellerin ne bağımsız şeyler ne de sadece isimler olarak değil, tikellerden soyutlanmış zihinsel kavramlar olarak var olduğunu savunmuş ve \'Sic et Non\' adlı eserinde çelişen kilise otoritelerini bir araya getirmiştir?',
