    text_tr: 'Demokritos\'un öğrencisi olan hangi Sokrates öncesi filozof, bilgiye ilişkin kuşkuculuğu, aktarılan \'hiçbirimiz hiçbir şey bilmiyoruz, hatta bilip bilmediğimizi bile bilmiyoruz\' sözüyle kendi kendini geçersiz kılan bir uca taşımıştır?',
    options: { A: 'Metrodorus of Chios', B: 'Anaxarchus', C: 'Pyrrho of Elis', D: 'Xeniades of Corinth', E: 'Monimus of Syracuse' },
    options_tr: { A: 'Sakızlı Metrodorus', B: 'Anaxarchus', C: 'Elisli Pyrrhon', D: 'Korintli Xeniades', E: 'Siraküzalı Monimus' },
    answer: 'A',
    difficulty: 3,
    explanation: 'Metrodorus of Chios, a student of Democritus, is recorded as declaring a radical skepticism denying that we can even know whether we know anything at all.',
