    text_tr: '\'Metodik okul\' adlı tıp ekolünün kurucusu olan hangi antik Septik hekim, bir hekimin bir hastalığın gizli nedenlerini değil yalnızca doğrudan gözlemlenebilir \'görünür\' özelliklerini kavraması gerektiğini savunarak, açık olmayan konularda yargıyı askıya alan Pyrrhoncu tutuma paralellik kurmuştur?',
    options: { A: 'Themison of Laodicea', B: 'Galen of Pergamon', C: 'Herophilus of Chalcedon', D: 'Erasistratus of Ceos', E: 'Asclepiades of Bithynia' },
