    text: 'Which named fallacy occurs when someone argues that a claim must be true because it has not been proven false, or must be false because it has not been proven true, illegitimately treating a lack of evidence against a position as evidence for it?',
    text_tr: 'Hangi adlandırılmış yanılgı, birinin bir iddianın yanlış olduğu kanıtlanmadığı için doğru olması gerektiğini, ya da doğru olduğu kanıtlanmadığı için yanlış olması gerektiğini öne sürerek, bir görüşe karşı kanıt eksikliğini o görüş lehine kanıt gibi haksız yere ele almasıyla oluşur?',
