    options_tr: { A: 'Cehalete başvurma (argumentum ad ignorantiam)', B: 'Konuyu varsayma (petitio principii)', C: 'Yanlış ikilem', D: 'Eş seslilik (anlam kayması)', E: 'Kaygan zemin' },
    answer: 'A',
    difficulty: 3,
    explanation: 'The argument from ignorance treats the absence of proof against a claim as proof for it, or vice versa, which is a well-known informal fallacy in logic.',
